/**
 * Deterministic HTML escaping for email templates (M11.4).
 *
 * Every dynamic value that reaches HTML output passes through `escapeHtml`.
 * This is the whole sanitization story for Forge V1 email: templates are
 * generated by us from a closed copy set, so the only untrusted input is
 * template DATA (a one-time URL, a policy-derived duration). Escaping those
 * deterministically is sufficient, and a browser-grade sanitizer would add a
 * dependency and a false sense of completeness for zero extra benefit.
 *
 * Rules this module guarantees:
 *
 * - `&` is replaced first (single pass over the original string), so escaping
 *   is idempotent in effect: `&amp;` can never be re-escaped into `&amp;amp;`
 *   by a second pass over already-escaped output.
 * - Both quote styles are escaped, so one function is safe in text nodes AND
 *   in double- or single-quoted attribute values.
 * - Nothing is stripped or "cleaned". Escaping changes representation, never
 *   content: `&lt;script&gt;` renders as the literal text `<script>`.
 * - No regex that could catastrophically backtrack: the pattern is a single
 *   character class.
 */

/** Character class, not alternation: one pass, no backtracking, no ordering bugs. */
const HTML_SENSITIVE = /[&<>"']/g;

const HTML_REPLACEMENTS: Record<string, string> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

/**
 * Escapes the five HTML-significant characters in a string.
 *
 * Deterministic and total: every input produces output, no input throws, and
 * the same input always yields the same output (templates must be renderable
 * identically in a test, in a CLI, and in production).
 */
export function escapeHtml(value: string): string {
  return value.replace(HTML_SENSITIVE, (character) => HTML_REPLACEMENTS[character] ?? character);
}